filtro_estado = [None] * {FILTERS_TOTAL}
def filtro_reiniciar(filtro):
    filtro[2][:] = []
    filtro[3] = 0

def filtro_configurar(inicio, filas, bloque):
    for indice in range(len(filas) // 2):
        tipo, parametro = filas[2 * indice:2 * indice + 2]
        tipo = int(tipo)
        valido = 0 <= parametro <= 1 if tipo == 2 else 1 <= parametro <= 15 and parametro == int(parametro)
        if not valido:
            rb_fail(bloque, "Parámetro de filtro inválido: ventana entera 1–15 o alfa 0–1")
        filtro_estado[inicio + indice] = [tipo, parametro, [], 0]

def filtro_obtener(numero, bloque):
    filtro = filtro_estado[numero - 1] if 1 <= numero <= len(filtro_estado) else None
    if filtro is None:
        rb_fail(bloque, "Configura el filtro al iniciar")
    return filtro

def filtro_actualizar(numero, lectura, bloque):
    filtro = filtro_obtener(numero, bloque)
    lectura = rb_finite(lectura, bloque)
    tipo, parametro, datos, ultimo = filtro
    if tipo == 2:
        filtro[3] = lectura if not datos else parametro * lectura + (1 - parametro) * ultimo
        datos[:] = [lectura]
    else:
        datos.append(lectura)
        if len(datos) > int(parametro):
            datos.pop(0)
        if tipo == 0:
            filtro[3] = sum(datos) / len(datos)
        else:
            orden = sorted(datos)
            mitad = len(orden) // 2
            filtro[3] = orden[mitad] if len(orden) % 2 else (orden[mitad - 1] + orden[mitad]) / 2
    return filtro[3]

struct filtro_datos {
    float datos[15] = {}, ultimo = 0, parametro = 0;
    uint8_t tipo = 0, cantidad = 0, siguiente = 0;
    bool configurado = false;
};
inline void filtro_reiniciar(filtro_datos& filtro) {
    filtro.cantidad = 0;
    filtro.siguiente = 0;
    filtro.ultimo = 0;
}

struct filtro_fila { const char* tipo; float parametro; };

inline filtro_datos& filtro_obtener(int numero, const char* bloque) {
    static filtro_datos vacio;
    int total = sizeof(filtro_estado) / sizeof(filtro_estado[0]);
    if (numero < 1 || numero > total || !filtro_estado[numero - 1].configurado) {
        rb_fail(bloque, "Configura el filtro al iniciar");
        return vacio;
    }
    return filtro_estado[numero - 1];
}
inline void filtro_configurar(int inicio, const filtro_fila* filas, int cantidad, const char* bloque) {
    for (int indice = 0; indice < cantidad; indice++) {
        int tipo = atoi(filas[indice].tipo);
        float parametro = filas[indice].parametro;
        bool valido = tipo == 2 ? parametro >= 0 && parametro <= 1 : parametro >= 1 && parametro <= 15 && floorf(parametro) == parametro;
        if (!valido) { rb_fail(bloque, "Parámetro de filtro inválido: ventana entera 1–15 o alfa 0–1"); return; }
        filtro_datos& filtro = filtro_estado[inicio + indice];
        filtro.tipo = tipo;
        filtro.parametro = parametro;
        filtro.configurado = true;
        filtro_reiniciar(filtro);
    }
}
inline float filtro_actualizar(int numero, float lectura, const char* bloque) {
    filtro_datos& filtro = filtro_obtener(numero, bloque);
    lectura = rb_finite(lectura, bloque);
    if (rb_failed) return 0;
    if (filtro.tipo == 2) {
        filtro.ultimo = filtro.cantidad == 0 ? lectura : filtro.parametro * lectura + (1 - filtro.parametro) * filtro.ultimo;
        filtro.cantidad = 1;
        return filtro.ultimo;
    }
    int ventana = int(filtro.parametro);
    filtro.datos[filtro.siguiente] = lectura;
    filtro.siguiente = (filtro.siguiente + 1) % ventana;
    if (filtro.cantidad < ventana) filtro.cantidad++;
    float orden[15], suma = 0;
    for (int i = 0; i < filtro.cantidad; i++) { orden[i] = filtro.datos[i]; suma += orden[i]; }
    if (filtro.tipo == 0) filtro.ultimo = suma / filtro.cantidad;
    else {
        for (int i = 1; i < filtro.cantidad; i++) {
            float valor = orden[i];
            int j = i - 1;
            while (j >= 0 && orden[j] > valor) { orden[j + 1] = orden[j]; j--; }
            orden[j + 1] = valor;
        }
        int mitad = filtro.cantidad / 2;
        filtro.ultimo = filtro.cantidad % 2 ? orden[mitad] : (orden[mitad - 1] + orden[mitad]) / 2;
    }
    return filtro.ultimo;
}

